import java.io.*;
import java.util.*;

public class Main {
    static byte[] buf = new byte[1 << 16];
    static int len = 0, ptr = 0;
    static InputStream in = System.in;

    static int read() throws IOException {
        if (ptr == len) { len = in.read(buf, 0, buf.length); ptr = 0; if (len <= 0) return -1; }
        return buf[ptr++];
    }

    static String next() throws IOException {
        int c = read();
        while (c <= ' ') c = read();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') { sb.append((char) c); c = read(); }
        return sb.toString();
    }

    static int[] parent, sz;

    static int find(int v) {
        while (parent[v] != v) { parent[v] = parent[parent[v]]; v = parent[v]; }
        return v;
    }

    public static void main(String[] args) throws IOException {
        int n = Integer.parseInt(next()), m = Integer.parseInt(next());
        HashMap<String, Integer> ids = new HashMap<>(4 * n + 4);
        for (int i = 0; i < n; i++) ids.put(next(), i);
        if (n == 1) { System.out.println(0); return; }
        long[] time = new long[m];
        int[] u = new int[m], v = new int[m];
        Integer[] order = new Integer[m];
        for (int i = 0; i < m; i++) {
            time[i] = Long.parseLong(next());
            u[i] = ids.get(next());
            v[i] = ids.get(next());
            order[i] = i;
        }
        Arrays.sort(order, (x, y) -> Long.compare(time[x], time[y]));
        parent = new int[n];
        sz = new int[n];
        for (int i = 0; i < n; i++) { parent[i] = i; sz[i] = 1; }
        int components = n;
        for (int i : order) {
            int a = find(u[i]), b = find(v[i]);
            if (a == b) continue;
            if (sz[a] < sz[b]) { int t = a; a = b; b = t; }
            parent[b] = a;
            sz[a] += sz[b];
            if (--components == 1) { System.out.println(time[i]); return; } // first moment everyone is connected
        }
        System.out.println(-1);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
	"sort"
)

func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<20)
	var n, m int
	fmt.Fscan(in, &n, &m)
	ids := make(map[string]int, n)
	for i := 0; i < n; i++ {
		var s string
		fmt.Fscan(in, &s)
		ids[s] = i
	}
	if n == 1 {
		fmt.Println(0)
		return
	}
	type entry struct{ time, u, v int }
	logs := make([]entry, m)
	for i := range logs {
		var s, t string
		fmt.Fscan(in, &logs[i].time, &s, &t)
		logs[i].u, logs[i].v = ids[s], ids[t]
	}
	sort.Slice(logs, func(i, j int) bool { return logs[i].time < logs[j].time })
	parent := make([]int, n)
	size := make([]int, n)
	for i := range parent {
		parent[i], size[i] = i, 1
	}
	find := func(v int) int {
		for parent[v] != v {
			parent[v] = parent[parent[v]]
			v = parent[v]
		}
		return v
	}
	components := n
	for _, l := range logs {
		a, b := find(l.u), find(l.v)
		if a == b {
			continue
		}
		if size[a] < size[b] {
			a, b = b, a
		}
		parent[b] = a
		size[a] += size[b]
		components--
		if components == 1 { // first moment everyone is connected
			fmt.Println(l.time)
			return
		}
	}
	fmt.Println(-1)
}
